"use strict";
let shopDetail='',shopDetailBack=false,shopDetailZoom=false,shopRoomZoom=false;
nightShop.rummaged=[];try{const saved=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion?.shop?.rummaged;if(Array.isArray(saved))nightShop.rummaged=['cards','battery','slip','reverse'].filter(x=>saved.includes(x));}catch{}
function shopRummage(id){if(!['cards','battery','slip','reverse'].includes(id))return false;if(id==='cards'&&!(shopObject==='drawer'&&nightShop.drawer))return false;if(id==='battery'&&!nightShop.rummaged.includes('cards'))return false;if(id==='slip'&&shopObject!=='counter')return false;if(id==='reverse'&&!(shopDetail==='photo'&&shopDetailBack))return false;if(!nightShop.rummaged.includes(id))nightShop.rummaged.push(id);tideSave();return true;}
const shopOldInspect=shopInspect;
shopInspect=function(id){shopDetail='';shopDetailBack=false;shopDetailZoom=false;return shopOldInspect(id);};
const shopOldObject=shopObjectMarkup;
function shopEvidence(id){if(!['receipt','photo','case','key'].includes(id))return false;if(id==='photo'&&!nightShop.rummaged.includes('battery'))return false;shopDetail=id;shopDetailBack=false;shopDetailZoom=false;return true;}
function shopEvidenceMarkup(){const backs={receipt:'背面铅笔字：卡别擦。回来取。\n旧巷 731 / 22:40',photo:'照片背面\n11.02 / 试音前\n雨棚下面站着的人不是许舟。\n左下角的蓝色印章：雾江照相馆',case:'盒脊上的旧胶痕\nB—17\n原标签下还有一个浅浅的“02”',key:'小铜钥匙的背面磨得发亮。匙柄上刻着：上。'};let face=shopDetailBack?`<div class="evidence-back">${escapeHTML(backs[shopDetail]).replaceAll('\n','<br>')}</div>`:shopDetail==='photo'?'<figure class="evidence-photo"><div class="evidence-photo-image" role="img" aria-label="旧站台照片，雨棚下的人影和路边的灯"></div><figcaption>雾江 / 旧车站 · 原创剧情道具配图</figcaption></figure>':shopDetail==='receipt'?'<div class="evidence-receipt">旧巷手机维修<br>2008.10.19 / NO.0731<hr>存储卡接触不良<br>不格式化 / 保留原件<br>收取：￥5.00<br><small>签字：许…<br>底部有一个指印</small></div>':shopDetail==='case'?'<div class="evidence-case"><span>17</span><small>2005 / …02</small></div>':'<div class="evidence-key">⚿</div>';return `<section class="evidence-inspector"><div class="evidence-stage ${shopDetailZoom?'is-zoomed':''}" tabindex="0" aria-label="物件细节，可滚动放大画面">${face}</div><nav><button data-evidence-flip>翻到${shopDetailBack?'正面':'背面'}</button><button data-evidence-zoom>${shopDetailZoom?'恢复大小':'放大细看'}</button><button data-evidence-close>放回原处</button></nav></section>`;}
shopObjectMarkup=function(){if(!shopObject)return '';if(shopDetail)return shopEvidenceMarkup();const old=shopOldObject().replace(/<div class="shop-drawer-open">[\s\S]*?<\/div>/,'');let visual='';if(shopObject==='counter')visual=`<div class="closeup-table counter-table" aria-label="玻璃柜台近景"><div class="counter-under">电池 ▦　耳机　SIM卡</div><button class="prop prop-ledger" data-shop-rummage="slip">翻开价目册</button>${nightShop.rummaged.includes('slip')?'<button class="prop prop-receipt" data-evidence="receipt">维修小票<br>NO.0731</button>':''}${nightShop.items.includes('case')?'<button class="prop prop-case" data-evidence="case">透明盒<br>17</button>':''}</div>`;
if(shopObject==='drawer')visual=nightShop.drawer?`<div class="closeup-table drawer-table ${nightShop.rummaged.includes('cards')?'cards-moved':''} ${nightShop.rummaged.includes('battery')?'battery-moved':''}" aria-label="打开的抽屉近景">${!nightShop.rummaged.includes('cards')?'<button class="prop prop-warranty" data-shop-rummage="cards">保修卡<br>移动电话三包凭证</button>':'<span class="moved-cards">挪开的保修卡</span>'}${nightShop.rummaged.includes('cards')&&!nightShop.rummaged.includes('battery')?'<button class="prop prop-battery" data-shop-rummage="battery">BL-5C<br>3.7V 电池</button>':''}${nightShop.rummaged.includes('battery')?'<button class="prop prop-photo" data-evidence="photo"><span class="drawer-photo-label">拾起照片</span></button>':''}<button class="prop prop-case" data-evidence="case">透明盒<br>17</button></div>`:'<div class="drawer-front"><span>木抽屉</span><i>━　◉　━</i></div>';
if(shopObject==='tray')visual='<div class="closeup-table tray-table"><span class="charger-wire">⌁⌁⌁⌁</span><div class="charger-body">万能充<br>充电　饱和</div><button class="prop prop-key" data-evidence="key" aria-label="放大查看铜钥匙">⚿</button></div>';
return old.replace('<article class="shop-closeup">','<article class="shop-closeup"><button data-shop-room>← 退后看整间店</button>'+visual);};
const shopPhotoMapBase=shopMap;
shopMap=function(){let html=shopPhotoMapBase();html=html.replace('class="shop-room"','class="shop-room photographic-room"');if(shopObject)html=html.replace(/<div class="shop-room photographic-room"[\s\S]*?<p class="shop-room-caption">[\s\S]*?<\/p>/,'');if(!shopObject)html=html.replace('<div class="shop-room photographic-room"',`<div class="shop-pan ${shopRoomZoom?'scene-zoomed':''}"><div class="shop-room photographic-room"`).replace('<p class="shop-room-caption">',`</div><button data-scene-zoom>${shopRoomZoom?'整店全景':'放大场景 / 横向查看'}</button><p class="shop-room-caption">`);return html;};
const shopPhotoEntranceBase=renderPhoneEntrance;
renderPhoneEntrance=function(){if(visitMode==='pc')return shopPhotoEntranceBase();return `<main class="oldlane-home"><section class="oldlane-hero"><div class="oldlane-hero-copy"><small>雾江 · 旧巷 / 2008</small><h1>总有一部旧手机，<br>还停在那一年。</h1><p>雨夜，你替老板照看一家手机店。<br>柜台里的旧物，还留着没说完的生活。</p><button data-shop-map>推开玻璃门</button>${tide.active?'<button data-tide-resume>继续手中的手机</button>':''}<span>原创慢节奏探索 · 本机自动存档</span></div></section><nav class="oldlane-modes"><button data-shop-map><b>夜班手机店</b><span>翻找旧物，拼起陌生人的过去</span></button><button data-tide-start><b>桌上的三部手机</b><span>短信、相册、QQ，和各自的年代</span></button></nav><details class="oldlane-museum"><summary>随便玩玩 / 选一部老手机听歌、上网、玩游戏</summary>${visitSwitcher()}${tideEntranceBase()}</details></main>`;};
const shopSlowAdvance=shopAdvance;
shopAdvance=function(){shopSlowAdvance();if(nightShop.events.includes('second')&&nightShop.callStage===2&&nightShop.rummaged.includes('reverse')&&!nightShop.events.includes('photo-sms')){nightShop.events.push('photo-sms');tideSave();}};
// Extend the persisted whitelist without replacing the existing save format.
try{const raw=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion?.shop;if(raw?.events?.includes('photo-sms')&&!nightShop.events.includes('photo-sms'))nightShop.events.push('photo-sms');}catch{}
const shopPhotoSms=tideSms;
tideSms=function(){if(tide.device==='black'&&tideView==='shop:photo-message'&&nightShop.events.includes('photo-sms'))return tideFrame('阿巡 / 00:27',`<div class="deep-chat"><p>你问的照片，我记得。</p><p>那天我不在雨棚下。我在拍照。</p><p>许舟后来把照片剪掉过一条边。你看到的是原来那张吗？</p><p>过了一会儿：先别回我。我在找底片。</p></div>${tideBtn('sms','返回收件箱')}`);const base=shopPhotoSms();return tide.device==='black'&&nightShop.events.includes('photo-sms')?base.replace('<div class="deep-contact-list">','<div class="deep-contact-list"><button data-shop-photo-message>阿巡 · 00:27<br>你看到的是原来那张吗？</button>'):base;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-shop-rummage],[data-evidence],[data-evidence-flip],[data-evidence-zoom],[data-evidence-close],[data-shop-room],[data-shop-photo-message],[data-scene-zoom]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-scene-zoom')){shopRoomZoom=!shopRoomZoom;return openShop();}if(b.hasAttribute('data-shop-photo-message')){tideView='shop:photo-message';return refreshPhone();}if(b.dataset.shopRummage)shopRummage(b.dataset.shopRummage);if(b.dataset.evidence)shopEvidence(b.dataset.evidence);if(b.hasAttribute('data-evidence-flip')){shopDetailBack=!shopDetailBack;if(shopDetail==='photo'&&shopDetailBack)shopRummage('reverse');}if(b.hasAttribute('data-evidence-zoom'))shopDetailZoom=!shopDetailZoom;if(b.hasAttribute('data-evidence-close'))shopDetail='';if(b.hasAttribute('data-shop-room')){shopObject='';shopDetail='';}openShop();});
